mapper.update:
WITH upsert AS
(
    UPDATE pay11_month_item
       SET pay11_item_amt = #{itemAmt}
     WHERE pay11_month_id = #{monthId}
       AND pay11_item_cd  = #{itemCode}
 RETURNING *
)
INSERT INTO pay11_month_item ( pay11_month_item_id, pay11_month_id, pay11_item_type, pay11_item_cd, pay11_item_amt )
SELECT f_create_seq(), #{monthId},
       ( SELECT pay20_item_type FROM pay20_item WHERE pay20_item_cd = #{itemCode} LIMIT 1 ),
       #{itemCode}, #{itemAmt}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

