UPDATE pay13_retire_tax
   SET

    pay13_income_deduct = #{itemAmt}, pay13_py_income_deduct = #{pyItemAmt}
    pay13_income_amt = #{itemAmt}, pay13_py_income_amt = #{pyItemAmt}
    pay13_tax_base = #{itemAmt}, pay13_py_tax_base = #{pyItemAmt}
    pay13_calc_tax = #{itemAmt}, pay13_py_calc_tax = #{pyItemAmt}
    pay13_decide_tax = #{itemAmt}, pay13_py_decide_tax = #{pyItemAmt}
    pay13_settle_tax = #{itemAmt}, pay13_py_settle_tax = #{pyItemAmt}

 WHERE pay13_month_id = #{monthId}

UPDATE pay13_retire_tax
   SET pay13_pre_office_pay_tax    = #{preOfficePayTax},
       pay13_py_pre_office_pay_tax = #{pyPreOfficePayTax},
       pay13_cur_office_pay_tax    = #{curOfficePayTax},
       pay13_py_cur_office_pay_tax = #{pyCurOfficePayTax}
 WHERE pay13_month_id = #{monthId}
